Util.AttachButtonFx = function(Button, squish)
	local stroke = Button:FindFirstChildOfClass("UIStroke")
	local baseT = stroke and stroke.Thickness or 1
	local basePos, baseSize = Button.Position, Button.Size
	local shift = (Vector2.new(0.5, 0.5) - Button.AnchorPoint) * Vector2.new(4, 2)
	local pressPos = basePos + UDim2.fromOffset(shift.X, shift.Y)
	local pressSize = baseSize - UDim2.fromOffset(4, 2)
	local hovering, pressing = false, false
	local running = {}
	local function play(inst, info, goal)
		local old = running[inst]
		if old then old:Cancel() end
		local tw = TweenService:Create(inst, info, goal)
		running[inst] = tw
		tw:Play()
	end
	local function refresh()
		if stroke then
			play(stroke, Util.TI.Hover, {Thickness = (hovering or pressing) and baseT + 1 or baseT})
		end
		if squish then
			if pressing then
				play(Button, Util.TI.Press, {Position = pressPos, Size = pressSize})
			else
				play(Button, Util.TI.Release, {Position = basePos, Size = baseSize})
			end
		end
	end
	local function ispointer(input)
		return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
	end
	Button.MouseEnter:Connect(function()
		hovering = true
		refresh()
	end)
	Button.MouseLeave:Connect(function()
		hovering = false
		pressing = false
		refresh()
	end)
	Button.InputBegan:Connect(function(input)
		if ispointer(input) then
			pressing = true
			refresh()
		end
	end)
	Button.InputEnded:Connect(function(input)
		if ispointer(input) then
			pressing = false
			refresh()
		end
	end)
end

