do
	local CDNVersion = 3
	local AllFileNames = {
		"lightinursoul.graphic.png",
		"letriangul.graphic.png",
	}
	local redownloadeverything = SaveData.CDNVersion ~= CDNVersion
	local theresassetsmissing = redownloadeverything
	for _,rfile in AllFileNames do
		local fil = "UhhhhhhReanim/Assets/" .. rfile
		local s, d = pcall(isfile, fil)
		if not (s and d) then
			theresassetsmissing = true
		end
	end
	if theresassetsmissing then
		local downloaded = 0
		local skipped = 0
		local assetsdownload = 0
		local downloadfile = function(meta)
			local fil = "UhhhhhhReanim/Assets/" .. meta.name
			if not redownloadeverything then
				local s, d = pcall(isfile, fil)
				if s and d then
					downloaded += 1
					return
				end
			end
			if not pcall(function()
				writefile(fil, game:HttpGet(meta.download_url))
			end) then skipped += 1 end
			downloaded += 1
		end
		local Downloading = Util.Instance("TextLabel", UIMainFrame)
		Downloading.AnchorPoint = Vector2.new(0.5, 0.5)
		Downloading.Position = UDim2.new(0.5, 0, 0.5, 0)
		Downloading.Size = UDim2.new(1, 0, 0, 0)
		Downloading.BackgroundColor3 = Color3.new(0, 0, 0)
		Downloading.BackgroundTransparency = 0.2
		Downloading.ClipsDescendants = true
		Downloading.BorderSizePixel = 0
		Downloading.TextColor3 = Color3.new(1, 1, 1)
		Downloading.TextSize = 20
		Downloading.Font = Enum.Font.Code
		Downloading.Text = "Fetching Assets metadata..."
		Util.ForceTextSize(Downloading)
		TweenService:Create(Downloading, TweenInfo.new(0.5), {
			Size = UDim2.new(1, 0, 0, 32)
		}):Play()
		task.wait(0.5)
		local s, assetsof = pcall(game.HttpGet, game, "https://api.github.com/repos/STEVE-916-create/Uhhhhhh/contents/uiassets/")
		if s and assetsof then
			s, assetsof = pcall(HttpService.JSONDecode, HttpService, assetsof)
			if s and assetsof then
				for i,file in assetsof do
					if not table.find(AllFileNames, file.name) then
						continue
					end
					assetsdownload += 1
					task.spawn(downloadfile, file)
				end
				repeat
					Downloading.Text = `Downloading assets {downloaded}/{assetsdownload}... ({skipped} skipped)`
					Downloading.BackgroundColor3 = Color3.new(0, 0, 0)
					task.wait()
				until downloaded == assetsdownload
				Downloading.Text = "Download complete! \\(^o^)/"
				Downloading.BackgroundColor3 = Color3.new(0, 1, 0)
				theresassetsmissing = false
			end
		end
		SaveData.CDNVersion = CDNVersion
		if theresassetsmissing then
			Downloading.Text = "Asset downloading failed. 3:"
			Downloading.BackgroundColor3 = Color3.new(1, 0, 0)
		end
		TweenService:Create(Downloading, TweenInfo.new(0.5), {
			Size = UDim2.new(1, 0, 0, 0),
			BackgroundColor3 = Color3.new(0, 0, 0),
		}):Play()
		task.wait(0.5)
		Downloading:Destroy()
	end
end

Util.GetCDNAsset = function(filename)
	local path = "UhhhhhhReanim/Assets/" .. filename
	local s, id = pcall(isfile, path)
	if s and id then
		s, id = pcall(getcustomasset, path)
		if s then return id end
	end
	return ""
end

Util.MakeTriforce = function(tris, color, dur)
	dur = dur or 8
	local function CreateTriangle(parent, radius, width, rotation, color)
		local height = (math.sqrt(3) / 2) * width
		local pivot = Util.Instance("Frame", parent)
		pivot.AnchorPoint = Vector2.new(0.5, 0.5)
		pivot.Position = UDim2.new(0.5, 0, 0.5, 0)
		pivot.Size = UDim2.new(1, 0, 1, 0)
		pivot.BackgroundTransparency = 1
		pivot.BorderSizePixel = 0
		pivot.Rotation = rotation
		local tri = Util.Instance("ImageLabel", pivot)
		tri.AnchorPoint = Vector2.new(0.5, 1)
		tri.Position = UDim2.new(0.5, 0, 0.5 - radius, 0)
		tri.Size = UDim2.new(width, 0, height, 0)
		tri.BackgroundTransparency = 1
		tri.BorderSizePixel = 0
		tri.Image = Util.GetCDNAsset("letriangul.graphic.png")
		local grey = math.max(color.R, color.G, color.B) * 0.5
		tri.ImageColor3 = Color3.new(grey, grey, grey)
		TweenService:Create(tri, TweenInfo.new(dur, Enum.EasingStyle.Linear), {
			ImageColor3 = color
		}):Play()
	end
	local radius = 0.1
	local pivot = Util.Instance("Frame")
	pivot.AnchorPoint = Vector2.new(0.5, 0.5)
	pivot.Position = UDim2.new(0.5, 0, 0.5, 0)
	pivot.BackgroundTransparency = 1
	pivot.BorderSizePixel = 0
	local width = 2 * radius * math.sin(math.pi / tris) * 2
	for i=1, tris do
		CreateTriangle(pivot, radius, width, (i / tris) * 360, color)
	end
	return pivot
end
Util.MakeText = function(text)
	text = text:upper()
	local ls = "BCDEIKOPQRSTUVYZ\\_`N^MJ"
	local lt = ""
	-- !, ", #, $, %, &, ', (, ), *, +, ,, -, ., /
	lt ..= "DDDDD@DFF@@@@@FSFSFSF@@@@@@@@@@@@@@EMMUKKTDD@@@@@DEEEEEDDBBBBBD@@@@@@@@@@@@@@@@@@@DE@@@G@@@@@@@@@DABBDEEI"
	-- numbers
	lt ..= "GJJJJJGDVDDDDSGJAGIISRAAGAARWJJSAAASIIRAARGIIRJJGSAABBDDGJJGJJGGJJHAAG"
	-- :, ;, <, =, >, ?, @
	lt ..= "@DD@DD@@DD@DE@@BDEDB@@@G@G@@@EDBDE@GJABD@D@@@@@@@"
	-- capital letters
	lt ..= "DFJSJJJRJJRJJRGJIIIJGRJJJJJRSIIRIISSIIRIIIHIILJJHJJJSJJJGDDDDDGAAAAAJHJKMOMKJIIIIIISJQNJJJJJJPNLJJGJJJJJGRJJRIIIGJJJNGCRJJRMKJGJIGAJGSDDDDDDJJJJJJGJJJJJFDJJJNQJJJJFDFJJJJFDDDDSABDEIS"
	local pixs = {}
	local totalsize = 0
	for i=0, 6 do
		local row = {}
		for j=1, text:len() do
			local c = text:byte(j, j)
			local w = 0
			if c ~= 0x20 then
				local k = (c - 33) * 7 + i
				w = lt:byte(k + 1, k + 1)
				if w ~= nil and w > 64 then
					w = ls:byte(w - 64, w - 64) - 65
				else
					w = 0
				end
			end
			for k=0, 5 do
				local h = (j - 1) * 6 + (4 - k)
				totalsize = math.max(totalsize, h + 1)
				local p = (w // math.pow(2, k)) % 2
				if p > 0 then
					row[h] = true
				end
			end
		end
		pixs[i] = row
	end
	local pivot = Util.Instance("Frame")
	pivot.AnchorPoint = Vector2.new(0.5, 0.5)
	pivot.Position = UDim2.new(0.5, 0, 0.5, 0)
	pivot.Size = UDim2.new(0, totalsize, 0, 7)
	pivot.BackgroundTransparency = 1
	pivot.BorderSizePixel = 0
	for i=0, 6 do
		local row = pixs[i]
		local olde = nil
		local olds = 0
		for j=0, totalsize - 1 do
			local pix = row[j]
			if pix == true then
				if olde ~= nil then
					olds += 1
					olde.Size = UDim2.new(olds / totalsize, 0, 1 / 7, 0)
				else
					olde = Util.Instance("Frame", pivot)
					olde.AnchorPoint = Vector2.new(0, 0)
					olde.Position = UDim2.new(j / totalsize, 0, i / 7, 0)
					olde.Size = UDim2.new(1 / totalsize, 0, 1 / 7, 0)
					olde.BackgroundTransparency = 1
					olde.BorderSizePixel = 0
					olds = 1
				end
			else
				olde = nil
				olds = 0
			end
		end
	end
	return pivot
end
Util.SetTextColor = function(text, color, tran)
	for _,v in text:GetChildren() do
		v.BackgroundColor3 = color
		v.BackgroundTransparency = tran
	end
end

local UISound = {}

UISound.Music = Util.Instance("Sound", UIMainFrame)
UISound.Music.Looped = false
UISound.Music.PlaybackRegionsEnabled = false
UISound.Music.Volume = 1
UISound.Music.PlaybackSpeed = 1

-- [RETRO SOUND] no song on execute anymore: the intro is a short sequence of retro sound effects
-- (power-on thump, PC-speaker beep, BIOS blips, rising arpeggio, "ding"), generated locally as tiny
-- 16-bit WAV files. No downloads and no copyrighted music. Timed to the intro animation below.
UISound.Retro = {}
UISound.NoAuto = false
UISound.IntroShift = 3.2 -- seconds added to the intro (longer BIOS boot log)
UISound.TypeSpeed = 90 -- characters per second of the boot log typing

-- [BOOT LOG] ONE list drives both the typed text in the intro AND its key-click / blip sounds.
-- Each row = {seconds to wait after the previous row, "text"}. To add a line, just add a row here;
-- timing and sound follow automatically. If you add many rows, raise UISound.IntroShift.
--   text starting with ">"  -> code line (low click)
--   text ending with "OK"   -> status line (high click + chord blip when it finishes typing)
--   mem = true              -> memory counter row
--   enter = true            -> last row (plays the "enter" key blip)
UISound.BootLines = {}
do
	local ver = UhhhhhhVersion:upper()
	local rows = {
		{0.30, "UHHHHHH BIOS V" .. ver},
		{0.18, "(C) STEVETHEREALONE"},
		{0.14, ""},
		{0.06, "CPU: LUAU 60MHZ .......... OK"},
		{0.30, "MEMORY TEST: ", mem = true},
		{0.57, "CHECKING EXECUTOR ........ OK"},
		{0.14, "> assert(request and getcustomasset)"},
		{0.12, "> assert(readfile and writefile)"},
		{0.12, "> assert(firetouchinterest)"},
		{0.12, "> local RS = game.RunService"},
		{0.12, "> local LP = Players.LocalPlayer"},
		{0.12, "> local Char = LP.Character"},
		{0.12, '> local Hum = Char:WaitForChild("Humanoid")'},
		{0.12, "> local Root = Char.HumanoidRootPart"},
		{0.12, "> local Cam = workspace.CurrentCamera"},
		{0.12, '> local TS = game:GetService("TweenService")'},
		{0.12, '> local Http = game:GetService("HttpService")'},
		{0.12, '> makefolder("UhhhhhhReanim")'},
		{0.12, "> getgenv().UHHHHHH = {}"},
		{0.14, "MOUNTING UIASSETS ........ OK"},
		{0.14, "LOADING AUDIO ENGINE ..... OK"},
		{0.14, "> require(REANIMATE.SYS)"},
		{0.18, "LOADING REANIMATE.SYS ..... OK"},
		{0.16, "HOOKING HEARTBEAT ........ OK"},
		{0.12, "> RS.Heartbeat:Connect(R.Step)"},
		{0.14, "BUILDING HAT MAP ......... OK"},
		{0.12, "> R.Hats = Char:GetAccessories()"},
		{0.14, "PATCHING NETWORK OWNER ... OK"},
		{0.12, '> sethiddenproperty(LP, "SimulationRadius", 1e9)'},
		{0.12, "> setmetatable(UHHHHHH, R)"},
		{0.12, "> R:Reanimate(Char)"},
		{0.12, "> task.spawn(R.Start)"},
		{0.12, ""},
		{0.08, "> RUN REANIM.EXE", enter = true},
	}
	local t = 0
	for _, r in rows do
		t += r[1]
		table.insert(UISound.BootLines, {t, r[2], mem = r.mem, enter = r.enter})
	end
end
do
	local RATE = 22050
	local PI2 = math.pi * 2
	local function sq(f, x, duty)
		return ((x * f) % 1) < duty and 1 or -1
	end
	local function tri(f, x)
		return 4 * math.abs((x * f) % 1 - 0.5) - 1
	end
	-- soft sample-and-hold noise (6 kHz) so static never sounds harsh
	local function noise(x, seed)
		local n = math.floor(x * 6000) + seed * 977
		return (math.sin(n * 12.9898) * 43758.5453) % 1 * 2 - 1
	end
	-- attack/decay envelope, x = seconds since the sound started
	local function ad(x, atk, dec)
		if x < atk then return x / atk end
		return math.exp(-(x - atk) / dec)
	end

	-- builds the intro: events are {start, end, fn(x)}. "wet" events also get a soft echo for a roomy feel.
	local function buildBoot()
		local dry, wet = {}, {}
		local function ev(t0, len, echo, fn)
			table.insert(echo and wet or dry, {t0, t0 + len, fn})
		end
		local function mix(list, t)
			local sum = 0
			if t < 0 then return 0 end
			for i = 1, #list do
				local e = list[i]
				if e[1] > t then break end
				if t < e[2] then
					local v = e[3](t - e[1])
					local left = e[2] - t
					if left < 0.008 then v *= left / 0.008 end -- tiny release, no clicks
					sum += v
				end
			end
			return sum
		end
		-- soft pulse / triangle note
		local function note(t0, f, len, amp, kind, dec, echo)
			ev(t0, len, echo ~= false, function(x)
				local e = ad(x, 0.004, dec or len * 0.35) * amp
				if kind == "tri" then
					return tri(f, x) * e
				end
				return (sq(f, x, 0.25) * 0.75 + tri(f * 2, x) * 0.25) * e
			end)
		end
		local function blip(t0, f, len, amp)
			ev(t0, len, false, function(x)
				return tri(f, x) * amp * ad(x, 0.003, len * 0.4)
			end)
		end
		-- exponential pitch sweep, smooth in and out
		local function sweep(t0, len, f0, f1, amp, kind)
			local r = f1 / f0
			local k = len / math.log(r)
			ev(t0, len, false, function(x)
				local ph = f0 * k * (r ^ (x / len) - 1)
				local w = kind == "tri" and (4 * math.abs(ph % 1 - 0.5) - 1) or math.sin(PI2 * ph)
				return w * amp * math.sin(math.pi * x / len)
			end)
		end
		local function hiss(t0, len, amp, seed, swell)
			ev(t0, len, false, function(x)
				local s = math.sin(math.pi * x / len)
				if swell then s = x / len end
				return noise(x, seed) * amp * s
			end)
		end

		local SH = UISound.IntroShift
		local function tick(t0, f)
			ev(t0, 0.03, false, function(x)
				return sq(f, x, 0.5) * 0.055 * ad(x, 0.001, 0.008)
			end)
		end

		-- 0.00  machine powers on: low thump + relay click
		ev(0, 0.35, false, function(x)
			local ph = 48 * x + (110 - 48) * (1 - math.exp(-30 * x)) / 30
			return math.sin(PI2 * ph) * 0.42 * ad(x, 0.003, 0.09)
		end)
		hiss(0.02, 0.03, 0.10, 1)

		-- 0.30  classic POST beep (softened PC speaker)
		ev(0.30, 0.14, false, function(x)
			return (sq(1000, x, 0.5) * 0.6 + math.sin(PI2 * 1000 * x) * 0.4) * 0.16 * math.min(1, x / 0.004)
		end)

		-- BIOS boot log: generated from UISound.BootLines (same times as the text on screen):
		-- key tick per line, rising memory-count blips, and a blip stepping through the C major chord
		-- every time an "OK" line finishes typing
		local chord, ci = {1046.5, 1318.5, 1568}, 0
		for _, ln in UISound.BootLines do
			local t0, text = ln[1], ln[2]
			if #text > 0 then
				tick(t0, text:sub(1, 1) == ">" and 1500 or 2200)
			end
			if ln.mem then
				for i = 0, 7 do
					blip(t0 + i * 0.07, 700 + i * 110, 0.05, 0.09)
				end
				blip(t0 + 0.58, 1568, 0.09, 0.12)
			elseif text:sub(-2) == "OK" then
				ci = ci % 3 + 1
				blip(t0 + #text / UISound.TypeSpeed + 0.02, chord[ci], 0.09, 0.11)
			end
			if ln.enter then
				blip(t0 + #text / UISound.TypeSpeed + 0.04, 262, 0.09, 0.16) -- "enter" key
			end
		end

		-- static burst -> soft rising zip into the logo
		sweep(2.40 + SH, 0.20, 300, 3200, 0.10, "tri")
		hiss(2.40 + SH, 0.20, 0.045, 2)

		-- logo wipes in: rising C major arpeggio
		local arp = {523.25, 659.25, 783.99, 1046.5, 1318.5, 1568, 2093}
		for i, f in arp do
			note(2.60 + SH + (i - 1) * 0.1, f, 0.2, 0.15, "sq", 0.06)
		end
		-- logo lands: warm chord + bass hit + sparkle
		note(3.30 + SH, 1046.5, 0.9, 0.12, "tri", 0.28)
		note(3.30 + SH, 1318.5, 0.9, 0.12, "tri", 0.28)
		note(3.30 + SH, 1568, 0.9, 0.12, "tri", 0.28)
		note(3.30 + SH, 2093, 0.5, 0.06, "sq", 0.15)
		ev(3.30 + SH, 1.0, false, function(x)
			return tri(130.81, x) * 0.26 * ad(x, 0.006, 0.4)
		end)
		blip(3.42 + SH, 1568, 0.06, 0.08) -- subtitle appears

		-- PRESS START: little two-note "coin" blip
		note(4.00 + SH, 987.77, 0.10, 0.10, "tri", 0.05)
		note(4.07 + SH, 1318.5, 0.22, 0.12, "tri", 0.10)

		-- logo dissolves: falling sparkle arpeggio
		local fall = {1568, 1318.5, 1046.5, 783.99, 659.25, 523.25, 392, 261.63}
		for i, f in fall do
			note(4.45 + SH + (i - 1) * 0.085, f, 0.16, 0.13 - i * 0.008, "tri", 0.07)
		end

		-- CRT collapses: soft static swell, then a falling "zzwoop"
		hiss(4.95 + SH, 0.30, 0.07, 3, true)
		sweep(5.256 + SH, 0.30, 2400, 120, 0.16, "sine")

		-- window ready: two-note ding
		note(5.40 + SH, 1046.5, 0.12, 0.14, "tri", 0.05)
		note(5.48 + SH, 1568, 0.40, 0.17, "tri", 0.15)

		table.sort(dry, function(a, b) return a[1] < b[1] end)
		table.sort(wet, function(a, b) return a[1] < b[1] end)
		return function(t)
			local v = mix(dry, t) + mix(wet, t) + 0.30 * mix(wet, t - 0.12) + 0.14 * mix(wet, t - 0.24)
			return math.clamp(v * 1.6, -0.95, 0.95)
		end
	end

	local sounds = {
		boot = {6.2 + UISound.IntroShift, buildBoot()},
		-- shown when "Skip Intro" is on: the same two-note ding
		ready = {0.5, function(t)
			local second = t >= 0.09
			local x = second and (t - 0.09) or t
			local f = second and 1568 or 1046.5
			return (tri(f, x) * 0.75 + sq(f, x, 0.25) * 0.1) * 0.28 * ad(x, 0.004, second and 0.14 or 0.05)
		end},
		click = {0.1, function(t)
			return sq(t < 0.045 and 1318.5 or 1760, t, 0.5) * 0.35 * (1 - t / 0.1)
		end},
	}
	pcall(makefolder, "UhhhhhhReanim")
	pcall(makefolder, "UhhhhhhReanim/Assets")
	for name, def in sounds do
		pcall(function()
			-- remove older versions of these sounds
			pcall(delfile, "UhhhhhhReanim/Assets/retro_" .. name .. "_v2.wav")
			pcall(delfile, "UhhhhhhReanim/Assets/retro_" .. name .. "_v3.wav")
			local sig = 0
			for _, ln in UISound.BootLines do
				sig = (sig * 31 + math.floor(ln[1] * 100) + #ln[2]) % 1000003
			end
			local path = "UhhhhhhReanim/Assets/retro_" .. name .. "_v5_" .. math.floor(UISound.IntroShift * 100) .. "_" .. sig .. ".wav"
			if not isfile(path) then
				local n = math.floor(def[1] * RATE)
				local parts, chunk = {}, {}
				for i = 0, n - 1 do
					local v = math.clamp(def[2](i / RATE), -1, 1)
					if i < 44 then v *= i / 44 end -- 2 ms fade in
					if n - 1 - i < 660 then v *= (n - 1 - i) / 660 end -- 30 ms fade out
					chunk[#chunk + 1] = string.pack("<i2", math.floor(v * 30000))
					if #chunk >= 4096 then
						parts[#parts + 1] = table.concat(chunk)
						table.clear(chunk)
					end
				end
				parts[#parts + 1] = table.concat(chunk)
				local data = table.concat(parts)
				writefile(path, "RIFF" .. string.pack("<I4", 36 + #data) .. "WAVEfmt " .. string.pack("<I4I2I2I4I4I2I2", 16, 1, 1, RATE, RATE * 2, 2, 16) .. "data" .. string.pack("<I4", #data) .. data)
			end
			UISound.Retro[name] = getcustomasset(path)
		end)
	end
end
UISound.PlayRetro = function(name)
	local id = UISound.Retro[name]
	if not id then return false end
	UISound.NoAuto = true
	UISound.Music.SoundId = id
	UISound.Music.Name = "Retro " .. name
	UISound.Music:Stop()
	UISound.Music.TimePosition = 0
	UISound.Music:Play()
	return true
end

local MusicPlayer = {}
MusicPlayer.Database = {
	{"UhhhhhhReanim/Assets/rickroll.mp3", "Rick roll", true}, -- 3rd value = embedded in this script (extracted on start, not downloaded)
	{"UhhhhhhReanim/Assets/toothless.mp3", "Toothless Dance", true},
}
pcall(function()
	local future = table.clone(MusicPlayer.Database)
	if isfile("UhhhhhhReanim/Muzik/nobuiltin") then
		table.clear(future)
	end
	for _,file in listfiles("UhhhhhhReanim/Muzik") do
		if isfile(file) and file:sub(-4, -1) == ".mp3" then
			table.insert(future, {file, file:sub(21, -5)})
		end
	end
	if #future > 0 then
		MusicPlayer.Database = future
	end
end)
MusicPlayer.Switching = false
MusicPlayer.Last = 1
MusicPlayer.PlayMusic = function(i, tries)
	UISound.NoAuto = false
	if MusicPlayer.Switching then return end
	MusicPlayer.Switching = true
	local explicit = i ~= nil
	local last = MusicPlayer.LastMusic
	if not i then
		if #MusicPlayer.Database <= 1 then
			i = 1
		else
			i = last
			while i == last do
				i = math.random(1, #MusicPlayer.Database)
				task.wait()
			end
		end
	end
	MusicPlayer.LastMusic = i
	local hi = MusicPlayer.Database[i]
	local soundid, soundname = hi[1], hi[2]
	local s, id = pcall(isfile, soundid)
	if s and id then
		s, id = pcall(getcustomasset, soundid)
		if s then
			soundid = id
		else
			soundid = ""
		end
	else
		soundid = ""
	end
	if #soundid == 0 then
		MusicPlayer.Switching = false
		tries = (tries or 0) + 1
		if explicit or tries >= #MusicPlayer.Database then
			Util.Notify(soundname .. " is still being prepared, try again in a few seconds")
			return
		end
		return MusicPlayer.PlayMusic(nil, tries)
	end
	UISound.Music.SoundId = soundid
	UISound.Music.Name = soundname
	UISound.Music:Stop()
	task.wait()
	UISound.Music.TimePosition = 0
	task.wait()
	UISound.Music:Play()
	task.wait()
	MusicPlayer.Switching = false
end
UISound.Music.Ended:Connect(function()
	if UISound.NoAuto then
		UISound.NoAuto = false
		return
	end
	MusicPlayer.PlayMusic()
end)

SaveData.SkipIntro = not not SaveData.SkipIntro
if SaveData.SkipIntro then
	UISound.PlayRetro("ready")
else
	UISound.Music.Volume = 0
	if UISound.PlayRetro("boot") then
		UISound.IntroW0 = os.clock()
		repeat RunService.RenderStepped:Wait() until UISound.Music.IsLoaded or os.clock() - UISound.IntroW0 > 3
		UISound.Music:Stop()
		task.wait()
		UISound.Music:Play()
	end
	UISound.Music.Volume = 1
	UISound.Music.TimePosition = 0
	UISound.IntroT0 = os.clock()
	-- [RETRO INTRO] brand-new execute animation. The old triforce / scrolltext intro was removed.
	-- Timeline (driven by the intro sound clock; S = UISound.IntroShift, ends at 5.256 + S seconds):
	--   0.3 - 2.4+S  DOS/BIOS boot log, rows in UISound.BootLines (scrolls like a real terminal)   2.4+S - 2.6+S  static burst
	--   2.6+S - 4.4+S  pixel logo + copper bars + starfield + blinking PRESS START
	--   4.4+S - 5.25+S  pixel dissolve out      end  CRT turn-on flash
	do
		local screen = Util.GetScreenSize()
		local sw, sh = screen.X, screen.Y
		local ver = UhhhhhhVersion:upper()
		local function smooth(x)
			x = math.clamp(x, 0, 1)
			return x * x * (3 - 2 * x)
		end
		local scene = Instance.new("Frame")
		scene.AnchorPoint = Vector2.new(0.5, 0.5)
		scene.Position = UDim2.new(0.5, 0, 0.5, 0)
		scene.BackgroundColor3 = Color3.new(0, 0, 0)
		scene.BackgroundTransparency = 0
		scene.BorderSizePixel = 0
		scene.Size = UDim2.new(1, 0, 1, 0)
		scene.ZIndex = 150
		scene.ClipsDescendants = true
		scene.Parent = UIMainFrame
		local content = Instance.new("Frame")
		content.AnchorPoint = Vector2.new(0.5, 0.5)
		content.Position = UDim2.new(0.5, 0, 0.5, 0)
		content.Size = UDim2.fromOffset(sw, sh)
		content.BackgroundTransparency = 1
		content.BorderSizePixel = 0
		content.Interactable = false
		content.Parent = scene
		local function box(z)
			local f = Instance.new("Frame")
			f.BorderSizePixel = 0
			f.ZIndex = z
			f.Interactable = false
			f.Parent = content
			return f
		end

		-- starfield (3 parallax layers of square pixels)
		local stars = {}
		for i = 1, 80 do
			local layer = math.random(1, 3)
			local f = box(1)
			f.Size = UDim2.fromOffset(layer + 1, layer + 1)
			local g = 0.3 + layer * 0.22
			f.BackgroundColor3 = Color3.new(g * 0.85, g * 0.9, g)
			stars[i] = {f = f, x = math.random() * sw, y = math.random() * sh, v = layer * 45 + 15}
		end

		-- copper bars (Amiga style raster bars, snapped to a pixel grid)
		local profile = {0.25, 0.5, 0.75, 1, 0.75, 0.5, 0.25}
		local barset = {}
		for b = 1, 3 do
			local stripes = {}
			for s = 1, 7 do
				stripes[s] = box(2)
			end
			barset[b] = {hue = (b - 1) * 0.28 + 0.02, phase = b * 1.1, stripes = stripes}
		end

		-- pixel text helper (uses the script's built-in 5x7 pixel font generator)
		local function pixtext(text, height, maxw, z)
			local p = Util.MakeText(text)
			p.Parent = content
			p.ZIndex = z
			local ratio = p.Size.X.Offset / p.Size.Y.Offset
			local px = math.max(1, math.floor(math.min(height, maxw / ratio) / 7))
			p.Size = UDim2.fromOffset(px * 7 * ratio, px * 7)
			local letters = {}
			for _, c in p:GetChildren() do
				table.insert(letters, {c, c.Position.X.Scale, c.Position.Y.Scale, math.random()})
			end
			return {pivot = p, letters = letters, px = px}
		end
		local function animtext(T, t, reveal, fadeout, wave, color)
			local px = T.px
			for _, L in T.letters do
				local f = L[1]
				if L[2] <= reveal and L[4] >= fadeout then
					f.Position = UDim2.new(L[2], 0, L[3], wave and math.floor(math.sin(L[2] * 9 + t * 5) * 1.6 + 0.5) * px or 0)
					if typeof(color) == "Color3" then
						f.BackgroundColor3 = color
					else
						f.BackgroundColor3 = Color3.fromHSV((L[2] * 0.9 - t * 0.5) % 1, 0.75, 1)
					end
					f.BackgroundTransparency = 0
				else
					f.BackgroundTransparency = 1
				end
			end
		end
		local logo = pixtext("UHHHHHH", sh * 0.26, sw * 0.88, 4)
		local shadow = pixtext("UHHHHHH", sh * 0.26, sw * 0.88, 3)
		local sub = pixtext("REANIMATE V" .. ver, sh * 0.06, sw * 0.8, 4)
		local press = pixtext("PRESS START", sh * 0.05, sw * 0.6, 4)
		sub.pivot.Position = UDim2.new(0.5, 0, 0.66, 0)
		press.pivot.Position = UDim2.new(0.5, 0, 0.82, 0)

		-- DOS boot text (rows live in UISound.BootLines, near the top of the sound section)
		local boot = Instance.new("TextLabel")
		boot.BackgroundTransparency = 1
		boot.BorderSizePixel = 0
		boot.Position = UDim2.fromOffset(math.max(12, sw * 0.04), math.max(12, sh * 0.05))
		boot.Size = UDim2.new(0.9, 0, 0.8, 0)
		boot.Font = Enum.Font.Code
		boot.TextSize = math.clamp(math.floor(sh / 38), 14, 28)
		boot.TextColor3 = Color3.fromRGB(80, 255, 100)
		boot.TextStrokeColor3 = Color3.fromRGB(0, 90, 25)
		boot.TextStrokeTransparency = 0.6
		boot.TextXAlignment = Enum.TextXAlignment.Left
		boot.TextYAlignment = Enum.TextYAlignment.Top
		boot.TextWrapped = false
		boot.Text = ""
		boot.ZIndex = 5
		boot.Parent = content

		-- CRT overlay: static burst, flicker, scanlines
		local stat = box(190)
		stat.BackgroundColor3 = Color3.new(1, 1, 1)
		stat.Size = UDim2.new(1, 0, 1, 0)
		stat.BackgroundTransparency = 1
		local flick = box(195)
		flick.BackgroundColor3 = Color3.new(0, 0, 0)
		flick.Size = UDim2.new(1, 0, 1, 0)
		flick.BackgroundTransparency = 0.93
		local crt = box(200)
		crt.BackgroundTransparency = 1
		crt.Size = UDim2.new(1, 0, 1, 0)
		local spacing = sh > 1200 and 4 or 3
		for y = 0, sh, spacing do
			local line = Instance.new("Frame")
			line.BackgroundColor3 = Color3.new(0, 0, 0)
			line.BackgroundTransparency = 0.78
			line.BorderSizePixel = 0
			line.Position = UDim2.fromOffset(0, y)
			line.Size = UDim2.new(1, 0, 0, 1)
			line.Parent = crt
		end

		while true do
			local dt = RunService.Heartbeat:Wait()
			local t = os.clock() - UISound.IntroT0
			if t >= 5.256 + UISound.IntroShift then break end
			local fadeout = smooth((t - 4.4 - UISound.IntroShift) / 0.85)
			local scenealpha = smooth((t - 2.5 - UISound.IntroShift) / 0.5) * (1 - fadeout)

			-- stars
			for _, s in stars do
				s.x -= s.v * dt
				if s.x < -6 then
					s.x = sw + 6
					s.y = math.random() * sh
				end
				s.f.Position = UDim2.fromOffset(math.floor(s.x), math.floor(s.y))
				s.f.BackgroundTransparency = 1 - scenealpha
			end

			-- copper bars
			local stripe = math.max(2, math.floor(sh / 160))
			local baralpha = smooth((t - 2.6 - UISound.IntroShift) / 0.4) * (1 - fadeout)
			for _, bar in barset do
				local cy = math.floor((0.5 + math.sin(t * 1.6 + bar.phase) * 0.3) * sh / stripe) * stripe
				for s, f in bar.stripes do
					f.Position = UDim2.fromOffset(0, cy + (s - 4) * stripe)
					f.Size = UDim2.new(1, 0, 0, stripe)
					f.BackgroundColor3 = Color3.fromHSV((bar.hue + t * 0.05) % 1, 0.85, profile[s])
					f.BackgroundTransparency = 1 - 0.65 * baralpha
				end
			end

			-- boot text
			if t < 2.4 + UISound.IntroShift then
				local out = {}
				for _, ln in UISound.BootLines do
					local el = t - ln[1]
					if el < 0 then break end
					local s = ln[2]
					if ln.mem then
						local m = math.min(640, math.floor(el / 0.55 * 640))
						s = s .. m .. "K" .. (m >= 640 and " OK" or "")
					else
						s = s:sub(1, math.floor(el * UISound.TypeSpeed))
					end
					table.insert(out, s)
				end
				while #out > math.max(6, math.floor(sh * 0.88 / (boot.TextSize * 1.15))) do
					table.remove(out, 1)
				end
				boot.Visible = true
				boot.Text = table.concat(out, "\n") .. ((math.floor(t * 4) % 2 == 0) and "_" or " ")
			else
				boot.Visible = false
			end

			-- logo: column wipe in, chunky sine wave, rainbow, drop shadow, pixel dissolve out
			local px = logo.px
			local bob = math.floor(math.sin(t * 3) * 1.5 + 0.5) * px
			local jx = (t > 4.2 + UISound.IntroShift) and (math.random(-1, 1) * px) or 0
			logo.pivot.Position = UDim2.new(0.5, jx, 0.4, bob)
			shadow.pivot.Position = UDim2.new(0.5, jx + px, 0.4, bob + px)
			local lr = (t - 2.6 - UISound.IntroShift) / 0.7
			animtext(logo, t, lr, fadeout, true, nil)
			animtext(shadow, t, lr, fadeout, true, Color3.fromRGB(45, 0, 80))
			animtext(sub, t, (t - 3.4 - UISound.IntroShift) / 0.5, fadeout, false, Color3.fromRGB(255, 176, 0))
			animtext(press, t, (t > 3.9 + UISound.IntroShift and math.floor((t - UISound.IntroShift) * 3) % 2 == 0) and 1 or -1, fadeout, false, Color3.fromRGB(120, 255, 255))

			-- CRT feel
			flick.BackgroundTransparency = 0.9 + math.random() * 0.06
			if (t >= 2.4 + UISound.IntroShift and t < 2.6 + UISound.IntroShift) or t >= 4.95 + UISound.IntroShift then
				stat.BackgroundTransparency = 0.65 + math.random() * 0.3
			else
				stat.BackgroundTransparency = 1
			end
		end

		-- [UI TRANSITION] CRT power-off: the screen collapses into a bright line, the line narrows to the
		-- window width, then the window powers on from that line (see the UIMainWindow reveal below)
		TweenService:Create(scene, TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.In), {
			Size = UDim2.new(1, 0, 0, 2)
		}):Play()
		TweenService:Create(scene, TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, 0, false, 0.2), {
			BackgroundColor3 = Color3.new(1, 1, 1)
		}):Play()
		task.delay(0.3, function()
			TweenService:Create(scene, TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				Size = UDim2.new(0, 360, 0, 2)
			}):Play()
		end)
		task.delay(0.5, function()
			scene:Destroy()
		end)
		Debris:AddItem(scene, 2)
		Util.IntroRevealAt = os.clock() + 0.5
	end
end

