local StylizedObjs = {}
local function Stylize(obj, options)
	options = options or {}
	-- [RETRO UI] sharp corners + chunky mitered border
	Util.Instance("UICorner", obj).CornerRadius = UDim.new(0, 0)
	local Out = Util.Instance("UIStroke", obj)
	Out.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	Out.Color = Color3.new(1, 1, 1)
	Out.LineJoinMode = Enum.LineJoinMode.Miter
	Out.Thickness = 2
	Out.Transparency = 0
	Out.Enabled = true
	obj.BackgroundColor3 = Color3.new(0, 0, 0)
	local Glos = {}
	local Shadow = nil
	if options.Glow == true then
		-- hard 6px pixel drop shadow (replaces the old soft neon glow)
		Shadow = Util.Instance("Frame", UIMainFrame)
		Util.LinkDestroyI2I(obj, Shadow)
		Shadow.Interactable = false
		Shadow.BorderSizePixel = 0
		Shadow.BackgroundTransparency = 0
		local function update()
			Shadow.AnchorPoint = obj.AnchorPoint
			Shadow.Position = obj.Position + UDim2.fromOffset(6, 6)
			Shadow.Size = obj.Size
			Shadow.Visible = obj.Visible
			Shadow.ZIndex = obj.ZIndex - 2
		end
		update()
		obj.Changed:Connect(update)
	end
	table.insert(StylizedObjs, {
		obj = obj,
		Out = Out,
		Glos = Glos,
		Shadow = Shadow,
		options = options,
	})
end
local ForceUIColor = nil
local ForceUIBGColor = nil
local UITextColor = Util.Instance("Color3Value")
UITextColor.Value = Color3.new(1, 1, 1)

-- [UI UPGRADE] smooth theme crossfade. The displayed color is blended between the previous
-- look and the new theme with smootherstep easing, so switching themes never "pops".
local ThemeFx = {
	Alpha = 1,
	Duration = 0.9,
	ToFore = nil,
	ToBack = nil,
	FromFore = nil, -- function(t) -> Color3 while blending
	FromBack = nil,
	TextFrom = Color3.new(1, 1, 1),
	TextTo = Color3.new(1, 1, 1),
}
ThemeFx.Ease = function(x)
	return x * x * x * (x * (x * 6 - 15) + 10)
end
ThemeFx.RawFore = function(force, t)
	if force then
		local si = math.sin(math.pi * 2 * t / 10)
		local h, s, v = force:ToHSV()
		if s < 0.2 then
			v *= 0.8 + si * 0.2
		else
			h += si * 0.01
		end
		return Util.LoopedHSV(h, s, v)
	end
	return Util.LoopedHSV(t / 10, 0.8, 1)
end
ThemeFx.RawBack = function(force, t)
	if force then
		local si = math.sin(math.pi * 2 * t / 10)
		local h, s, v = force:ToHSV()
		if s < 0.2 then
			if v > 0.5 then
				v *= 0.95 + si * 0.05
			else
				v *= 1.05 + si * 0.05
			end
		else
			h += si * 0.01
		end
		return Util.LoopedHSV(h, s, v)
	end
	return Color3.new(0, 0, 0)
end
local function GetUIColor(t)
	local to = ThemeFx.RawFore(ThemeFx.ToFore, t)
	if ThemeFx.Alpha >= 1 then return to end
	return ThemeFx.FromFore(t):Lerp(to, ThemeFx.Ease(ThemeFx.Alpha))
end
local function GetUIBGColor(t)
	local to = ThemeFx.RawBack(ThemeFx.ToBack, t)
	if ThemeFx.Alpha >= 1 then return to end
	return ThemeFx.FromBack(t):Lerp(to, ThemeFx.Ease(ThemeFx.Alpha))
end
ThemeFx.Step = function(dt)
	if ThemeFx.Alpha >= 1 then return end
	ThemeFx.Alpha = math.min(1, ThemeFx.Alpha + dt / ThemeFx.Duration)
	UITextColor.Value = ThemeFx.TextFrom:Lerp(ThemeFx.TextTo, ThemeFx.Ease(ThemeFx.Alpha))
	if ThemeFx.Alpha >= 1 then
		ThemeFx.FromFore, ThemeFx.FromBack = nil, nil
		UITextColor.Value = ThemeFx.TextTo
	end
end
ThemeFx.Set = function(fore, back, text, instant)
	-- freeze whatever is currently on screen so an interrupted transition continues from it
	local snapAlpha, snapToFore, snapToBack = ThemeFx.Alpha, ThemeFx.ToFore, ThemeFx.ToBack
	local snapFromFore, snapFromBack = ThemeFx.FromFore, ThemeFx.FromBack
	local function snapFore(t)
		local to = ThemeFx.RawFore(snapToFore, t)
		if snapAlpha >= 1 then return to end
		return snapFromFore(t):Lerp(to, ThemeFx.Ease(snapAlpha))
	end
	local function snapBack(t)
		local to = ThemeFx.RawBack(snapToBack, t)
		if snapAlpha >= 1 then return to end
		return snapFromBack(t):Lerp(to, ThemeFx.Ease(snapAlpha))
	end
	ThemeFx.ToFore, ThemeFx.ToBack = fore, back
	ThemeFx.TextFrom, ThemeFx.TextTo = UITextColor.Value, text
	if instant then
		ThemeFx.Alpha = 1
		ThemeFx.FromFore, ThemeFx.FromBack = nil, nil
		UITextColor.Value = text
	else
		ThemeFx.FromFore, ThemeFx.FromBack = snapFore, snapBack
		ThemeFx.Alpha = 0
	end
end
local function RegisterTextLabel(obj)
	if obj:IsA("TextLabel") or obj:IsA("TextButton") then
		obj.TextColor3 = UITextColor.Value
		Util.LinkDestroyI2C(obj, UITextColor.Changed:Connect(function(val)
			obj.TextColor3 = val
		end))
	end
	if obj:IsA("TextBox") then
		local h, s, v = UITextColor.Value:ToHSV()
		obj.TextColor3 = UITextColor.Value
		obj.PlaceholderColor3 = Color3.fromHSV(h, s, 0.5 + (v - 0.5) * 0.4)
		Util.LinkDestroyI2C(obj, UITextColor.Changed:Connect(function(val)
			h, s, v = val:ToHSV()
			obj.TextColor3 = val
			obj.PlaceholderColor3 = Color3.fromHSV(h, s, 0.5 + (v - 0.5) * 0.4)
		end))
	end
end
local function UpdateGrads(t)
	local c = GetUIColor(t)
	local bgc = GetUIBGColor(t)
	local h, s, v = bgc:ToHSV()
	local bgcd = Color3.fromHSV(h, s, v * 0.9)
	local h2, s2, v2 = c:ToHSV()
	local glc = c
	glc = c:Lerp(bgc, math.clamp((v - v2) * 10, 0, 1))
	local shc = c:Lerp(Color3.new(0, 0, 0), 0.55)
	for _,grad in StylizedObjs do
		local obj, Out, Glos, options = grad.obj, grad.Out, grad.Glos, grad.options
		Out.Color = c
		if grad.Shadow then
			grad.Shadow.BackgroundColor3 = shc
		end
		if options.Depthed then
			obj.BackgroundColor3 = bgcd
		else
			obj.BackgroundColor3 = bgc
		end
		for _,v in Glos do
			v.ImageColor3 = glc
		end
	end
end
local function SetUITheme(index, instant)
	local UIThemes = {
		-- RGB/Default
		{},
		-- ALONE
		{Fore = Color3.new(1, 1, 1), SndClick = "rbxassetid://81715128969224"},
		-- Oxide
