		-- Genesis V4 - Neptunian V
		{Fore = Color3.fromHex("7733FF"), Back = Color3.fromHex("161330"), SndClick = "rbxassetid://80526571264304"},
		-- Crimson
		{Fore = Color3.new(0.9, 0, 0), Back = Color3.new(0.05, 0, 0)},
