	-- [RETRO] the cool scene gets the same moving "UHHHHHH" as the intro: big wavy rainbow pixel logo
	-- with a drop shadow, a wavy rainbow title, and soft copper bars behind the triforce
	local function MakeWavy(str, px, anchorY, pos, z)
		local p = Util.MakeText(str)
		local ratio = p.Size.X.Offset / p.Size.Y.Offset
		p.Size = UDim2.fromOffset(px * 7 * ratio, px * 7)
		p.AnchorPoint = Vector2.new(0.5, anchorY)
		p.Position = pos
		p.ZIndex = z
		p.Parent = CracktroFrame
		local letters = {}
		for _, c in p:GetChildren() do
			table.insert(letters, {c, c.Position.X.Scale, c.Position.Y.Scale})
		end
		return {pivot = p, letters = letters, px = px}
	end
	local function AnimWavy(T, t, wave, rainbow, color)
		local px = T.px
		for _, L in T.letters do
			local f = L[1]
			f.Position = UDim2.new(L[2], 0, L[3], math.floor(math.sin(L[2] * 9 + t * 5) * wave + 0.5) * px)
			f.BackgroundColor3 = rainbow and Color3.fromHSV((L[2] * 0.9 - t * 0.5) % 1, 0.75, 1) or color
			f.BackgroundTransparency = 0
		end
	end
	local logoShadow = MakeWavy("UHHHHHH", 3, 0, UDim2.new(0.5, 3, 0, 17), 2)
	local logo = MakeWavy("UHHHHHH", 3, 0, UDim2.new(0.5, 0, 0, 14), 4)
	local titleWavy = {pivot = text, letters = {}, px = 1}
	for _, c in text:GetChildren() do
