		if dotTween then dotTween:Cancel() end
		if Lever.Value then
			dotTween = TweenService:Create(SwitchDot, Util.TI.Pop, {Size = UDim2.fromOffset(DOT, DOT)})
		else
			dotTween = TweenService:Create(SwitchDot, Util.TI.Shrink, {Size = UDim2.fromOffset(0, 0)})
		end
		dotTween:Play()
	end
	Lever.Changed:Connect(updatesw)
	Button.Activated:Connect(function()
		Lever.Value = not Lever.Value
	end)
	return Lever, ButtonText
