-- [EMBEDDED MUSIC] the tracks "Rick roll" and "Toothless Dance" of the UI music list are embedded in this script
-- (re-encoded to small mp3s). On start each one is extracted once to UhhhhhhReanim/Assets/. If the file already
-- exists it is left alone, so you can swap in the original full-quality mp3 (same file name) any time.
MusicPlayer.ExtractEmbedded = function(path, getparts)
	local s, exists = pcall(isfile, path)
	if s and exists then return end
	local parts = getparts()
	local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local B = {}
	for i = 1, 64 do
		B[alphabet:byte(i)] = i - 1
	end
	local out, groups = {}, 0
	for _, part in parts do
		local str = part:gsub("%s", "")
		local pad = (str:sub(-2) == "==") and 2 or ((str:sub(-1) == "=") and 1 or 0)
		local piece = table.create(#str // 4)
		for i = 1, #str, 4 do
			local a, b, c, d = string.byte(str, i, i + 3)
			local n = (B[a] or 0) * 262144 + (B[b] or 0) * 4096 + (B[c] or 0) * 64 + (B[d] or 0)
			piece[#piece + 1] = string.char(math.floor(n / 65536), math.floor(n / 256) % 256, n % 256)
			groups += 1
			if groups % 20000 == 0 then task.wait() end
		end
		local decoded = table.concat(piece)
		if pad > 0 then decoded = decoded:sub(1, #decoded - pad) end
		out[#out + 1] = decoded
	end
	pcall(makefolder, "UhhhhhhReanim")
	pcall(makefolder, "UhhhhhhReanim/Assets")
	pcall(writefile, path, table.concat(out))
end
